package org.dromara.sports.tables.d01.governance_grant;
import cn.dev33.satoken.stp.StpUtil;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.dromara.common.core.enums.UserType;
import org.dromara.common.satoken.utils.LoginHelper;
import org.dromara.sports.api.GovernanceScopeApi;
import org.dromara.sports.platform.core.*;
import org.springframework.stereotype.Service;
import java.util.*;
import static org.dromara.sports.platform.core.BusinessSupport.*;

@Service @RequiredArgsConstructor
public class GovernanceService implements GovernanceScopeApi,CapabilityProvider {
    private final ScopedJdbc db;private final ObjectMapper json;
    private static final Set<String> READS=Set.of("asp_organization_application","asp_governance_grant","asp_organization","asp_account_tenant_principal","asp_staff_grant","asp_event","asp_competition_unit","asp_registration","asp_fee_obligation","asp_complaint");
    public List<CapabilityDefinition> capabilities(){return List.of(
        capability(json,"government.assignAdmission","分配指定入驻申请审核责任","asp_governance_grant",false,true,Set.of("admin"),"",READS,Set.of("asp_organization_application"),"applicationId","sysUserId","expectedVersion"),
        capability(json,"government.qualify","暂停或恢复主办方办赛资格","asp_governance_grant",false,true,Set.of("government","admin"),"sports:government:qualify",READS,Set.of("asp_organization","asp_notification"),"organizationId","status","reason","expectedVersion"),
        capability(json,"government.grant","设置指定主办方的政府管理范围","asp_governance_grant",false,true,Set.of("admin"),"",READS,Set.of("asp_governance_grant"),"organizationId","sysUserId","permissions","status"));}
    public boolean allows(Long user,Long org,String permission){if(user==null||org==null)return false;return db.count("SELECT count(*) FROM asp_governance_grant WHERE sys_user_id=? AND organization_id=? AND status='active' AND (valid_until IS NULL OR valid_until>CURRENT_TIMESTAMP) AND permissions @> ?::jsonb",user,org,"[\""+permission+"\"]")>0;}
    private void human(){if(TrustedRunContext.current()!=null||!LoginHelper.isLogin()||LoginHelper.getUserType()!=UserType.SYS_USER)throw fail("请由政府管理岗位本人办理",403);}
    private void scope(long org,String permission){human();if(!LoginHelper.isSuperAdmin()&&!allows(LoginHelper.getUserId(),org,permission))throw fail("该主办方不在你的管理范围",403);}
    public JsonNode preview(String code,JsonNode in){if(code.equals("government.assignAdmission")){human();if(!LoginHelper.isSuperAdmin())throw fail("审核责任须由平台负责人分配",403);return safeJson(json,db.one("SELECT id,name,status,assigned_reviewer_id,version FROM asp_organization_application WHERE id=?",id(in,"applicationId")));}long org=id(in,"organizationId");scope(org,code.equals("government.qualify")?"qualify":"summary");var row=db.one("SELECT id,name,status,version FROM asp_organization WHERE id=?",org);if(row==null)throw fail("主办方不存在",404);return safeJson(json,row);}
    public JsonNode execute(String code,JsonNode in){if(code.equals("government.assignAdmission")){human();if(!LoginHelper.isSuperAdmin())throw fail("审核责任须由平台负责人分配",403);long app=id(in,"applicationId"),user=id(in,"sysUserId");if(db.count("SELECT count(*) FROM sys_user u WHERE u.user_id=? AND u.status='0' AND u.del_flag='0' AND EXISTS(SELECT 1 FROM sys_user_role ur JOIN sys_role r ON r.role_id=ur.role_id AND r.status='0' JOIN sys_role_menu rm ON rm.role_id=r.role_id JOIN sys_menu m ON m.menu_id=rm.menu_id WHERE ur.user_id=u.user_id AND m.perms='sports:organization:review')",user)==0)throw fail("请选择具备入驻审核岗位的有效账号",409);if(db.update("UPDATE asp_organization_application SET assigned_reviewer_id=?,version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=? AND version=? AND status='pending'",user,app,in.path("expectedVersion").asInt(-1))!=1)throw fail("申请状态已变化，请刷新",409);return reference(json,"applicationId",app,"assigned");}long org=id(in,"organizationId");db.lock("governance:"+org);String state=text(in,"status",16);
        if(code.equals("government.grant")){human();if(!LoginHelper.isSuperAdmin())throw fail("管理范围须由平台授权负责人设置",403);long user=id(in,"sysUserId");if(db.count("SELECT count(*) FROM sys_user WHERE user_id=? AND status='0' AND del_flag='0'",user)==0)throw fail("请选择有效政府岗位账号",409);if(!Set.of("active","revoked").contains(state))throw fail("授权状态无效",400);if(db.count("SELECT count(*) FROM asp_organization WHERE id=?",org)==0)throw fail("主办方不存在",404);var permissions=new TreeSet<>(Arrays.asList(text(in,"permissions",100).split(",")));if(!Set.of("qualify","summary","complaint").containsAll(permissions))throw fail("只支持资格管理、必要汇总和投诉协调权限",400);db.update("UPDATE asp_governance_grant SET status='revoked',version=version+1,update_time=CURRENT_TIMESTAMP WHERE organization_id=? AND sys_user_id=? AND status='active'",org,user);if(state.equals("active"))db.update("INSERT INTO asp_governance_grant(id,sys_user_id,organization_id,permissions,status) VALUES (?,?,?,?::jsonb,'active')",nextId(),user,org,safeJson(json,permissions).toString());return reference(json,"organizationId",org,state);}
        scope(org,"qualify");if(!Set.of("certified","restricted").contains(state))throw fail("请选择暂停或恢复",400);String reason=text(in,"reason",1000);int n=db.update("UPDATE asp_organization SET status=?,version=version+1,update_time=CURRENT_TIMESTAMP WHERE id=? AND version=? AND status IN ('certified','restricted')",state,org,in.path("expectedVersion").asInt(-1));if(n!=1)throw fail("资格状态已变化，请刷新后核对",409);
        for(var a:db.list("SELECT DISTINCT g.account_id,o.tenant_id FROM asp_staff_grant g JOIN asp_organization o ON o.id=g.organization_id WHERE g.organization_id=? AND g.status='active'",org)){var content=json.createObjectNode();content.put("title",state.equals("restricted")?"办赛资格已暂停":"办赛资格已恢复");content.put("body",reason);content.put("targetPath","/portal/organization");db.update("INSERT INTO asp_notification(id,tenant_id,recipient_account_id,business_type,business_id,business_revision,purpose,content,dedupe_key) VALUES (?,?,?,'organization',?,?,'qualification',?::jsonb,?)",nextId(),a.get("tenant_id"),a.get("account_id"),org,in.path("expectedVersion").asInt()+1,content.toString(),"org:"+org+":"+(in.path("expectedVersion").asInt()+1)+":"+a.get("account_id"));}return reference(json,"organizationId",org,state);
    }
    public JsonNode dashboard(){human();if(!LoginHelper.isSuperAdmin()&&!StpUtil.hasPermission("sports:government:summary"))throw fail("当前岗位未获汇总权限",403);String filter=LoginHelper.isSuperAdmin()?"":" AND EXISTS(SELECT 1 FROM asp_governance_grant g WHERE g.organization_id=o.id AND g.sys_user_id=? AND g.status='active' AND (g.valid_until IS NULL OR g.valid_until>CURRENT_TIMESTAMP) AND g.permissions @> '[\"summary\"]'::jsonb)";Object[] args=LoginHelper.isSuperAdmin()?new Object[]{}:new Object[]{LoginHelper.getUserId()};return safeJson(json,db.list("SELECT o.id,o.name,o.status,o.version,(SELECT count(*) FROM asp_event e WHERE e.organization_id=o.id) AS event_count,(SELECT count(*) FROM asp_registration r JOIN asp_competition_unit u ON u.id=r.unit_id JOIN asp_event e ON e.id=u.event_id WHERE e.organization_id=o.id AND r.status IN ('submitted','approved')) AS registration_count,(SELECT count(*) FROM asp_complaint c WHERE c.tenant_id=o.tenant_id AND c.status NOT IN ('resolved','rejected')) AS open_complaints FROM asp_organization o WHERE 1=1"+filter+" ORDER BY o.name",args));}
    public JsonNode administration() {
        human();
        if(!LoginHelper.isSuperAdmin()) throw fail("责任分配须由平台负责人办理",403);
        var result=json.createObjectNode();
        result.set("applications",safeJson(json,db.list("SELECT id,name,status,version,assigned_reviewer_id FROM asp_organization_application WHERE status='pending' ORDER BY create_time")));
        result.set("reviewers",safeJson(json,db.list("SELECT DISTINCT u.user_id,u.nick_name FROM sys_user u JOIN sys_user_role ur ON ur.user_id=u.user_id JOIN sys_role r ON r.role_id=ur.role_id WHERE u.status='0' AND u.del_flag='0' AND r.status='0' AND r.role_key='sports_government' ORDER BY u.nick_name")));
        result.set("organizations",safeJson(json,db.list("SELECT id,name,status FROM asp_organization WHERE status IN('certified','restricted') ORDER BY name")));
        result.set("grants",safeJson(json,db.list("SELECT g.id,g.sys_user_id,g.organization_id,g.permissions::text AS permissions,g.status,u.nick_name,o.name AS organization_name FROM asp_governance_grant g JOIN sys_user u ON u.user_id=g.sys_user_id JOIN asp_organization o ON o.id=g.organization_id WHERE g.status='active' ORDER BY g.create_time")));
        return result;
    }
}
